// ---------------------------------------------------------------------------
// Helper: lấy mã thứ i của protocol p
// ---------------------------------------------------------------------------
inline uint32_t bf_code_at(uint8_t proto_idx, uint32_t code_idx) {
    if (proto_idx >= BF_PROTOCOL_COUNT) return 0;
    const BFProtocol& p = BF_PROTOCOLS[proto_idx];
    if (code_idx >= p.key_count) return 0;
    return pgm_read_dword(&bf_codes[p.code_offset + code_idx]);
}

// ---------------------------------------------------------------------------
// Helper: tính T_us để rf_replay_send_raw_code hiểu đúng timing.
// Firmware dùng EV1527-like encoding: sync=1T_hi/31T_lo, bit0=1/3, bit1=3/1
// Với CAME/NICE khác timing, ta convert T_us tương ứng cho send_raw_code.
// Xem bruteforce.cpp để biết cách dùng chính xác hơn.
// ---------------------------------------------------------------------------
inline uint16_t bf_payload_bits(uint8_t proto_idx) {
    if (proto_idx >= BF_PROTOCOL_COUNT) return 0;
    return BF_PROTOCOLS[proto_idx].bits;
}
